{
	switch (prio) {
	case RTIO_PRIO_HIGH:
		return MAX(0, CONFIG_RTIO_WORKQ_PRIO_MED - 1);
	case RTIO_PRIO_LOW:
		return CONFIG_RTIO_WORKQ_PRIO_MED + 1;
	case RTIO_PRIO_NORM:
	default:
		return CONFIG_RTIO_WORKQ_PRIO_MED;
	}
}

static void rtio_work_handler(struct k_p4wq_work *work)
{
	struct rtio_work_req *req = CONTAINER_OF(work, struct rtio_work_req, work);
	struct rtio_iodev_sqe *iodev_sqe = req->iodev_sqe;
	rtio_work_handler_t handler = req->handler;
	int idx = req - rtio_work_reqs;

	if (handler != NULL) {
		handler(iodev_sqe);
	}

	atomic_clear_bit(rtio_work_req_in_use, idx);
	atomic_dec(&rtio_work_req_used_count);
}

struct rtio_work_req *rtio_work_req_alloc(void)
{
	for (int i = 0; i < RTIO_WORKQ_MAX_REQ; i++) {
		if (!atomic_test_and_set_bit(rtio_work_req_in_use, i)) {
			struct rtio_work_req *req = &rtio_work_reqs[i];
